mapper.select:
SELECT SUM(t1.`free_amount`) as `total_amount`, SUM(t1.`receivable_amount`) as `receivable_amount`, SUM(t1.`discount_amount`) as `discount_amount` FROM `parking_pay_record` t1
and t1.`pay_time` >= #{period.begin}
and t1.`pay_time` <= #{period.end}

SELECT a.`id` `id`, a.`identify_id` `identifyId`, a.`vehicle_no` `vehicleNo`, a.`pay_type` `payType`, a.`receivable_amount` `receivableAmount`, a.`pay_time` `payTime`, a.`parking_times` `parkingTimes`, a.`free_amount` `freeAmount`, a.`discount_amount` `discountAmount` FROM `parking_pay_record` a
and a.`vehicle_no` like concat('%', #{param.keyword}, '%')
and a.`pay_time` >= #{period.begin}
and a.`pay_time` <= #{period.end}
order by a.`pay_time` DESC, a.`id` DESC

SELECT b.`identify_id` `identifyId`, b.`access_time` `accessInTime`, b.`parking_info_code` `parkingInfoCode`, b.`parking_info_name` `parkingInfoName` FROM `parking_access_record` b WHERE b.`access_type` = 'ACCESS_IN' AND b.`identify_id` IN
#{identifyId}
ORDER BY b.`identify_id`, b.`access_time` DESC, b.`id` DESC
